"""Build ``golden.json`` for the ``playbook`` kind from ``restart_runbook.md``.

Run it from PowerShell on this repo's venv interpreter, never a bare python:

    & .\\.venv\\Scripts\\python.exe tests\\fixtures\\playbook\\make_golden.py

It imports ``doc_tools``, which pulls the Dagster defs and so ``python-magic``;
under the Bash tool that import never returns (see CLAUDE.md).

There is no generator for the fixture: markdown is trivially deterministic, so
the file IS the fixture and ``fixture.md_sha256`` pins it. There is also NO
``nondeterministic`` block: nothing on this path is model-derived.

The golden is built THROUGH THE DISPATCHER, so it records what the registry row
actually runs; a row edited to declare a different pass moves this file.
"""
from __future__ import annotations

import hashlib
import io
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

MD = os.path.join(HERE, "restart_runbook.md")
GOLDEN = os.path.join(HERE, "golden.json")

REPO_NAME = "playbooks"
REPO_URL = "https://git.example.invalid/ops/playbooks.git"
REPO_PATH = "runbooks/restart_runbook.md"


def build() -> dict:
    from doc_tools.passes.dispatch import PassContext, run_passes_for_kind
    from doc_tools.utils.content_kind import KIND_MAPPING
    from doc_tools.utils.md_chunks import chunk_markdown, playbook_doc_id

    with io.open(MD, "rb") as fh:
        raw = fh.read()
    text = raw.decode("utf-8")
    doc_id = playbook_doc_id(REPO_NAME, REPO_PATH)

    ctx = PassContext(text=text, doc_id=doc_id)
    results = run_passes_for_kind("playbook", ctx)
    outline = None
    for result in results:
        if result.status == "ok" and result.name.endswith("playbook_outline"):
            outline = result.value

    chunks = chunk_markdown(text, doc_id, REPO_URL, REPO_PATH)
    row = KIND_MAPPING["playbook"]
    return {
        "_comment": (
            "GENERATED by tests/fixtures/playbook/make_golden.py. The pinned "
            "heading tree and chunk ids of restart_runbook.md, read "
            "deterministically by the pass the `playbook` row declares. "
            "Nothing here is model-derived."
        ),
        "fixture": {
            "md": "restart_runbook.md",
            "md_sha256": hashlib.sha256(raw).hexdigest(),
            "doc_id": doc_id,
            "source": REPO_URL,
            "path": REPO_PATH,
        },
        "row": {
            "kind": row.kind,
            "domain_type": row.domain_type,
            "passes": list(row.passes),
            "outputs": list(row.outputs),
            "ingress_prefix": row.ingress_prefix,
            "file_suffixes": list(row.file_suffixes or ()),
        },
        "pass_results": [{"name": r.name, "status": r.status} for r in results],
        "outline": outline.as_dict() if outline is not None else None,
        "chunks": [
            {k: c[k] for k in ("chunk_id", "section_id", "heading",
                               "heading_path", "synthetic", "source", "path")}
            for c in chunks
        ],
    }


def main() -> int:
    golden = build()
    text = json.dumps(golden, indent=2, sort_keys=False) + "\n"
    if "--check" in sys.argv:
        current = ""
        if os.path.exists(GOLDEN):
            with io.open(GOLDEN, encoding="utf-8") as fh:
                current = fh.read()
        if current != text:
            print("GOLDEN DRIFT: regenerate with make_golden.py")
            return 1
        print("golden matches")
        return 0
    with io.open(GOLDEN, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(text)
    print("wrote", GOLDEN)
    print("chunks:", len(golden["chunks"]))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
